from scapy.all import rdpcap, DNS, DNSQR
import re

def analyze_dns_traffic(pcap_file: str) -> dict:
    packets = rdpcap(pcap_file)
    subdomains = set()
    long_domains = set()
    high_entropy = set()
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}

    for pkt in packets:
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR):
            domain = pkt[DNSQR].qname.decode('utf-8').lower().rstrip('.')
            subdomains.add(domain)

            # DGA: Långa domännamn
            if len(domain) > 40:
                long_domains.add(domain)

            # DGA: Hög entropi (slumpmässiga tecken)
            if len(domain) > 10:
                entropy = -sum((c / len(domain)) * __import__('math').log2(c / len(domain)) 
                               for c in [domain.count(char) for char in set(domain)])
                if entropy > 3.8:
                    high_entropy.add(domain)

            # Tunneling/Exfiltration: Stora TXT-responser eller mängder unika subdomäner
            if pkt.haslayer(DNS) and pkt[DNS].ancount > 0:
                for i in range(pkt[DNS].ancount):
                    if pkt[DNS].an[i].type == 16: # TXT record
                        if len(str(pkt[DNS].an[i].rdata)) > 100:
                            suspicious["tunneling"].append(domain)

    # Aggregera DGA
    suspicious["dga"] = list(long_domains.union(high_entropy))

    # Exfiltration: Många unika subdomäner indikerar data-out
    if len(subdomains) > 50:
        suspicious["exfiltration"] = list(subdomains)[:10] # Exempel på topp 10

    return suspicious
```

