import re

def harden_ssh_config(config_path: str) -> dict:
    recommendations = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "PubkeyAuthentication": "yes",
        "Protocol": "2",
        "X11Forwarding": "no",
        "MaxAuthTries": "3",
        "ClientAliveInterval": "300",
        "ClientAliveCountMax": "2"
    }

    findings = {}

    try:
        with open(config_path, 'r') as f:
            content = f.read()

        for key, recommended_value in recommendations.items():
            match = re.search(rf"^{key}\s+(.*)", content, re.MULTILINE)
            if match:
                current_value = match.group(1).split()[0] # Get first token
                if current_value.lower() != recommended_value:
                    findings[key] = {"current": current_value, "recommended": recommended_value}
            else:
                findings[key] = {"current": "not set", "recommended": recommended_value}

    except FileNotFoundError:
        return {"error": f"File not found: {config_path}"}

    return findings
