#!/usr/bin/env python3
import os, glob, time, subprocess, sys

LOG_DIR = sys.argv[1] if len(sys.argv) > 1 else "/var/log"
MAX_DAYS = 7

def rotate_logs():
    now = time.time()
    for log_file in glob.glob(os.path.join(LOG_DIR, "*.log")):
        if os.path.isfile(log_file):
            timestamp = now - os.path.getmtime(log_file)
            if timestamp > 86400: # Äldre än 1 dag
                archive_name = f"{log_file}.{time.strftime('%Y%m%d', time.localtime(os.path.getmtime(log_file)))}"
                if not os.path.exists(archive_name):
                    os.rename(log_file, archive_name)

def compress_old():
    now = time.time()
    for archive in glob.glob(os.path.join(LOG_DIR, "*.log.*")):
        if os.path.isfile(archive) and not archive.endswith(".gz"):
            if now - os.path.getmtime(archive) > (MAX_DAYS * 86400):
                subprocess.run(["gzip", archive])

if __name__ == "__main__":
    rotate_logs()
    compress_old()
